mapper.select:
SELECT p.id, p.product_name, p.category_id, p.pic, p.detail_html, p.status, p.is_hot, p.hot_sort, p.create_time, c.category_name AS category_name, s.id AS sku_id, s.product_id, s.sku_code, s.price, s.cost_price, s.stock, s.pic AS sku_pic, s.weight, s.volume, s.status AS sku_status, s.create_time AS sku_create_time, s.update_time AS sku_update_time, sa.id AS attr_id, sa.sku_id, sa.product_id, sa.attr_name, sa.attr_value, sa.attr_id AS attr_type_id, sa.attr_value_id, sa.create_time AS attr_create_time FROM pms_product p LEFT JOIN pms_category c ON p.category_id = c.id LEFT JOIN pms_sku s ON s.product_id = p.id LEFT JOIN pms_sku_attr sa ON sa.sku_id = s.id
AND p.product_name LIKE CONCAT('%', #{keyword}, '%')
AND p.status = #{status}
AND p.category_id = #{categoryId}
ORDER BY p.create_time DESC
